const tabId = 2126149062;
const cardData = await browserjs(tabId, () => {
  // Let's inspect all elements that contain event info
  // Often in Luma they are links or divs with role="button" or links with event codes
  const cards = [];
  const links = document.querySelectorAll('a');
  links.forEach(a => {
    if (a.href.match(/luma\.com\/[a-z0-9-]+$/i) && !['discover', 'pricing', 'app', 'nyc', 'signin'].some(x => a.href.endsWith(x))) {
      cards.push({
        url: a.href,
        text: a.innerText.trim()
      });
    }
  });
  return cards;
});

console.log("Found cards:", JSON.stringify(cardData, null, 2));

const tabId = 2126149062;
const events = await browserjs(tabId, () => {
  const result = [];
  const links = document.querySelectorAll('a[href*="/"]');
  links.forEach(a => {
    // Check if the link or its parent container has event info
    const container = a.closest('div') || a;
    const href = a.getAttribute('href');
    if (href && !href.startsWith('/signin') && !href.startsWith('/pricing') && !href.startsWith('/app') && !href.startsWith('/discover') && !href.startsWith('/nyc') && !href.includes('?') && href.length > 2) {
      result.push({
        href: a.href,
        outerHTMLSnippet: a.outerHTML.slice(0, 200),
        parentText: a.parentElement ? a.parentElement.innerText.replace(/\n+/g, ' | ').trim() : ''
      });
    }
  });
  return result;
});

console.log("Events from links:", JSON.stringify(events.slice(0, 10), null, 2));

const tabId = 2126149062;

// Let's scroll down to load more events on luma.com/nyc
const allEvents = await browserjs(tabId, async () => {
  const gathered = new Map();
  for (let i = 0; i < 8; i++) {
    window.scrollBy(0, 1500);
    await new Promise(r => setTimeout(r, 600));

    document.querySelectorAll('a.event-link, a[aria-label]').forEach(a => {
      const label = a.getAttribute('aria-label');
      const href = a.href;
      if (label && href && !href.includes('signin') && !href.includes('pricing') && !href.includes('discover')) {
        const text = a.closest('div')?.parentElement?.innerText?.replace(/\n+/g, ' | ') || '';
        if (!gathered.has(href)) {
          gathered.set(href, { label, href, text });
        }
      }
    });
  }
  return Array.from(gathered.values());
});

