const tabId = 2126149062;

// Let's scroll down to load more events on luma.com/nyc
const allEvents = await browserjs(tabId, async () => {
  const gathered = new Map();
  for (let i = 0; i < 8; i++) {
    window.scrollBy(0, 1500);
    await new Promise(r => setTimeout(r, 600));

    document.querySelectorAll('a.event-link, a[aria-label]').forEach(a => {
      const label = a.getAttribute('aria-label');
      const href = a.href;
      if (label && href && !href.includes('signin') && !href.includes('pricing') && !href.includes('discover')) {
        const text = a.closest('div')?.parentElement?.innerText?.replace(/\n+/g, ' | ') || '';
        if (!gathered.has(href)) {
          gathered.set(href, { label, href, text });
        }
      }
    });
  }
  return Array.from(gathered.values());
});

console.log("Total unique events found:", allEvents.length);
console.log("First 15 found:");
allEvents.slice(0, 20).forEach((e, i) => console.log(`${i+1}. [${e.label}](${e.href}) -> ${e.text.slice(0, 100)}`));

