const lumaUrls = [
  "https://luma.com/reading-3407", // Slow Summer at Brooklyn Bridge Park
  "https://luma.com/wuo6ynis", // Robot Hackathon
  "https://luma.com/nw5wa8dw", // get lost (& play with florals)
  "https://luma.com/47rsvjir", // RUNTIME: Build + Demo Day!
  "https://luma.com/u88u3qme", // Creator Night
  "https://luma.com/bm9mhi4p", // Find a Climate Week Buddy!
  "https://luma.com/c27um8t9", // Not only possible (Queens)
  "https://luma.com/r58e2nbe", // 1% for the Planet Volunteer Hackathon
  "https://luma.com/age-k45c", // Move for Longevity
  "https://luma.com/outrunco2", // OutRun CO2 Club
  "https://luma.com/um14sps2" // The Angel Market
];

const scrapeTabId = 2126149065 || (await tool.tabs_context({ _: "" })).pages.find(p => p.url.includes('rrv38lta'))?.tabId;

const scraped = [];

for (const url of lumaUrls) {
  await tool.navigate({ tabId: scrapeTabId, url });
  await tool.wait_for({ tabId: scrapeTabId, condition: "dom_settled", timeout_ms: 4000 });
  const text = (await browser.read({ tabId: scrapeTabId, maxChars: 6000 })).text;
  scraped.push({ url, textLength: text.length, preview: text.slice(0, 1500) });
}

console.log("Scraped", scraped.length, "pages.");
for (let i = 0; i < scraped.length; i++) {
  console.log(`=== EVENT ${i+1}: ${lumaUrls[i]} ===`);
  console.log(scraped[i].preview);
}

